const ENV_URL = (import.meta as any).env?.VITE_SUPABASE_URL || '';
const ENV_KEY = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY || '';

async function supabase(path:string, options:RequestInit={}){
 if(!ENV_URL||!ENV_KEY) throw new Error('لم يتم إعداد اتصال قاعدة البيانات. أضف VITE_SUPABASE_URL و VITE_SUPABASE_ANON_KEY في Vercel.');
 const token=localStorage.getItem('ss_access_token');
 const headers:any={'apikey':ENV_KEY,'Content-Type':'application/json',...(options.headers||{})};
 if(token) headers.Authorization=`Bearer ${token}`;
 const res=await fetch(`${ENV_URL}/rest/v1/${path}`,{...options,headers});
 const raw=await res.text();
 let data:any=null; try{data=raw?JSON.parse(raw):null}catch{data=raw}
 if(!res.ok){const msg=typeof data==='string'?data:(data?.message||data?.hint||data?.details||data?.error_description||data?.error||`HTTP ${res.status}`);throw new Error(msg)}
 return data;
}
function growChatTextarea(el:HTMLTextAreaElement){el.style.height='auto';el.style.height=Math.min(el.scrollHeight,132)+'px';}
function parseDate(row:any):string|null{
 const raw=row?.['تاريخ الميلاد']??row?.birth_date??row?.['Birth Date']??'';
 const nowYear=new Date().getFullYear();
 const digits=(v:any)=>String(v??'').replace(/[٠-٩]/g,(d)=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d))).replace(/[۰-۹]/g,(d)=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)));
 const valid=(year:number,month:number,day:number)=>{
  year=Math.trunc(year);month=Math.trunc(month);day=Math.trunc(day);
  if(year<1900||year>nowYear||month<1||month>12||day<1||day>31)return null;
  const d=new Date(Date.UTC(year,month-1,day));
  if(d.getUTCFullYear()!==year||d.getUTCMonth()!==month-1||d.getUTCDate()!==day)return null;
  return `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
 };
 const num=(v:any)=>{const n=Number(digits(v).trim());return Number.isFinite(n)?n:NaN;};
 const day=num(row?.['يوم الميلاد']??row?.day??'');
 const month=num(row?.['شهر الميلاد']??row?.month??'');
 const year=num(row?.['سنة الميلاد']??row?.year??'');
 if(Number.isFinite(day)&&Number.isFinite(month)&&Number.isFinite(year)){
  const d=valid(year,month,day);if(d)return d;
 }
 if(raw instanceof Date&&!isNaN(raw.getTime())){
  const d=valid(raw.getFullYear(),raw.getMonth()+1,raw.getDate());if(d)return d;
 }
 if(typeof raw==='number'&&Number.isFinite(raw)){
  // Excel serial date. SheetJS may return this when cellDates=false.
  const serial=Math.trunc(raw);
  if(serial>=1&&serial<=60000){
   const excelEpoch=Date.UTC(1899,11,30);
   const d=new Date(excelEpoch+serial*86400000);
   const out=valid(d.getUTCFullYear(),d.getUTCMonth()+1,d.getUTCDate());if(out)return out;
  }
 }
 const text=digits(raw).trim();
 if(!text)return null;
 let m=text.match(/^(\d{1,2})\s*[\/\-.]\s*(\d{1,2})\s*[\/\-.]\s*(\d{4})$/);
 if(m){const d=valid(Number(m[3]),Number(m[2]),Number(m[1]));if(d)return d;}
 m=text.match(/^(\d{4})\s*[\/\-.]\s*(\d{1,2})\s*[\/\-.]\s*(\d{1,2})$/);
 if(m){const d=valid(Number(m[1]),Number(m[2]),Number(m[3]));if(d)return d;}
 // Last chance for a numeric string representing an Excel serial.
 const serial=num(text);
 if(Number.isFinite(serial)&&serial>=1&&serial<=60000){
  const d=new Date(Date.UTC(1899,11,30)+Math.trunc(serial)*86400000);
  return valid(d.getUTCFullYear(),d.getUTCMonth()+1,d.getUTCDate());
 }
 return null;
}
