function playNotificationSound(){
 try{
  const Ctx=window.AudioContext||((window as any).webkitAudioContext);
  if(!Ctx)return;
  const ctx=new Ctx();
  const now=ctx.currentTime;
  const gain=ctx.createGain();
  gain.gain.setValueAtTime(0.0001,now);
  gain.gain.exponentialRampToValueAtTime(0.16,now+0.02);
  gain.gain.exponentialRampToValueAtTime(0.0001,now+0.55);
  gain.connect(ctx.destination);
  [880,1174].forEach((freq,i)=>{
   const osc=ctx.createOscillator();
   osc.type='sine';
   osc.frequency.setValueAtTime(freq,now+i*0.13);
   osc.connect(gain);
   osc.start(now+i*0.13);
   osc.stop(now+0.28+i*0.13);
  });
  window.setTimeout(()=>ctx.close().catch(()=>{}),800);
 }catch{}
}

async function authRequest(path:string, body:any){
 if(!ENV_URL||!ENV_KEY) throw new Error('لم يتم إعداد اتصال قاعدة البيانات.');
 const res=await fetch(`${ENV_URL}/auth/v1/${path}`,{method:'POST',headers:{apikey:ENV_KEY,'Content-Type':'application/json'},body:JSON.stringify(body)});
 const raw=await res.text(); let data:any=null; try{data=raw?JSON.parse(raw):null}catch{}
 if(!res.ok) throw new Error(data?.error_description||data?.msg||data?.message||'فشل تسجيل الدخول'); return data;
}

export default function App(){
 const [session,setSession]=useState<Profile|null>(null); const [booting,setBooting]=useState(true); const [tab,setTab]=useState<Tab>('bible'); const [selectedSector,setSelectedSector]=useState('primary'); const [selectedClass,setSelectedClass]=useState(''); const [refresh,setRefresh]=useState(0);
 useEffect(()=>{(async()=>{
   const token=localStorage.getItem('ss_access_token');
   const cachedRaw=localStorage.getItem('ss_cached_profile');
   let cached:Profile|null=null;
   try{cached=cachedRaw?JSON.parse(cachedRaw):null}catch{}
   if(cached) setSession(cached);
   if(!token||!localStorage.getItem('ss_user_id')){setBooting(false);return}
   try{
     const p=await supabase('profiles?select=*&id=eq.'+encodeURIComponent(localStorage.getItem('ss_user_id')||'')+'&limit=1');
     if(p?.[0]){setSession(p[0]);localStorage.setItem('ss_cached_profile',JSON.stringify(p[0]));}
     else if(!cached) { localStorage.removeItem('ss_access_token'); localStorage.removeItem('ss_user_id'); }
   }catch{
     // Keep the cached session when offline or when the API is temporarily unavailable.
     // Server-backed actions will sync again automatically once connectivity returns.
   }
   setBooting(false)
 })()},[]);
 if(booting) return <div className="loading-screen"><div className="loading-cross">✚</div><b>جاري فتح خِدمة...</b></div>;
 if(!session) return <Login onLogin={setSession}/>;
 return <AppShell session={session} onSessionUpdate={setSession} tab={tab} setTab={setTab} selectedSector={selectedSector} setSelectedSector={setSelectedSector} selectedClass={selectedClass} setSelectedClass={setSelectedClass} refresh={()=>setRefresh(v=>v+1)} refreshKey={refresh} onLogout={()=>{localStorage.removeItem('ss_access_token');localStorage.removeItem('ss_user_id');localStorage.removeItem('ss_cached_profile');setSession(null)}}/>;
}

function Login({onLogin}:{onLogin:(p:Profile)=>void}){
 const [username,setUsername]=useState(''); const [password,setPassword]=useState(''); const [show,setShow]=useState(false); const [error,setError]=useState(''); const [busy,setBusy]=useState(false);
 async function submit(e:FormEvent){e.preventDefault(); if(!username||!password){setError('أدخل اسم المستخدم وكلمة المرور.');return} setBusy(true);setError('');try{const res=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.trim(),password})});const raw=await res.text();let d:any={};try{d=raw?JSON.parse(raw):{}}catch{}if(!res.ok)throw new Error(d.error||'اسم المستخدم أو كلمة المرور غير صحيحة.');localStorage.setItem('ss_access_token',d.access_token);localStorage.setItem('ss_user_id',d.user.id);const p=await supabase('profiles?select=*&id=eq.'+encodeURIComponent(d.user.id)+'&limit=1');if(!p?.[0]){localStorage.removeItem('ss_access_token');localStorage.removeItem('ss_user_id');throw new Error('الحساب موجود لكن ملف الصلاحيات غير موجود.');}localStorage.setItem('ss_cached_profile',JSON.stringify(p[0]));onLogin(p[0])}catch(err:any){setError(err.message||'تعذر تسجيل الدخول')}finally{setBusy(false)}}
 return <div className="login-page" dir="rtl"><div className="login-visual"><div className="login-cross">☦</div><div className="login-quote">« دَعُوا الأَوْلَادَ يَأْتُونَ إِلَيَّ وَلاَ تَمْنَعُوهُمْ، لأَنَّ لِمِثْلِ هَؤُلاَءِ مَلَكُوتَ السَّمَاوَاتِ »<small>متى ١٩: ١٤</small></div><div className="login-brand"><b>كنيسة السيدة العذراء مريم بسقيل</b><span>نظام إدارة الخدمة الكنسية · خِدمة</span></div></div><div className="login-card-wrap"><form className="login-card" onSubmit={submit}><div className="login-icon">✚</div><p className="login-eyebrow"><Church size={15}/> كنيسة السيدة العذراء مريم بسقيل</p><h1>تسجيل الدخول</h1><p className="login-sub">ادخل بحسابك للوصول إلى القطاع والصلاحيات المخصصة لك.</p><label>اسم المستخدم<input value={username} onChange={e=>setUsername(e.target.value)} type="text" autoComplete="username"/></label><label>كلمة المرور<div className="password-field"><input type={show?'text':'password'} value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password"/><button type="button" onClick={()=>setShow(!show)}>{show?<EyeOff size={16}/>:<Eye size={16}/>}</button></div></label>{error&&<div className="login-error">{error}</div>}<button className="login-submit" disabled={busy}>{busy?'جاري الدخول...':'تسجيل الدخول'} <ChevronLeft size={18}/></button><p className="login-note">مسؤول الموقع · أب الكنيسة · أمين الخدام · خادم · مخدوم</p></form></div></div>
}

